import{_ as t,o,c as a,ag as r}from"./chunks/framework.BPmc_f4o.js";const p=JSON.parse('{"title":"AI-assisted Protocol authoring (LineText, BinaryStream)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/protocol-authoring.md","filePath":"guides/protocol-authoring.md"}'),n={name:"guides/protocol-authoring.md"};function s(i,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-assisted-protocol-authoring-linetext-binarystream" tabindex="-1">AI-assisted Protocol authoring (LineText, BinaryStream) <a class="header-anchor" href="#ai-assisted-protocol-authoring-linetext-binarystream" aria-label="Permalink to &quot;AI-assisted Protocol authoring (LineText, BinaryStream)&quot;">​</a></h1><p>Muxit&#39;s AI chat can add devices that don&#39;t speak SCPI — Arduino sketches, cheap hobby meters, dataloggers, Modbus-RTU sensors, custom embedded hardware. The flow mirrors the <a href="./ai-scpi-authoring.html">AI-assisted SCPI flow</a> but uses the <a href="./../reference/drivers/linetext.html">LineText</a> or <a href="./../reference/drivers/binary-stream.html">BinaryStream</a> protocols depending on what the device emits.</p><div class="tip custom-block"><p class="custom-block-title">Subscription required</p><p>Same as SCPI authoring — <strong>Maker tier or higher</strong> for Muxit&#39;s managed AI, or point your own Claude Desktop / Claude Code / ChatGPT at Muxit&#39;s MCP server for Free-tier access. See <a href="./ai.html#ai-features-by-tier">AI features by tier</a>.</p></div><h2 id="decide-which-protocol" tabindex="-1">Decide which protocol <a class="header-anchor" href="#decide-which-protocol" aria-label="Permalink to &quot;Decide which protocol&quot;">​</a></h2><p>The AI usually picks for you after one <code>discover_serial_device</code> call. The decision tree:</p><table tabindex="0"><thead><tr><th>Device</th><th>Protocol</th></tr></thead><tbody><tr><td>Arduino sketch, hobby PSU, custom embedded that prints lines (<code>TEMP: 25.5\\n</code>)</td><td><a href="./../reference/drivers/linetext.html">LineText</a></td></tr><tr><td>Modbus-RTU sensor, datalogger with fixed-byte frames, cheap thermometer with binary response</td><td><a href="./../reference/drivers/binary-stream.html">BinaryStream</a></td></tr><tr><td>Oscilloscope, multimeter, power supply, function generator — anything that says it speaks SCPI</td><td><a href="./../reference/drivers/scpi.html">Scpi</a> — use the <a href="./ai-scpi-authoring.html">SCPI authoring guide</a> instead</td></tr></tbody></table><p>When in doubt, say <em>&quot;I don&#39;t know what protocol this device uses&quot;</em> — the AI calls <code>discover_serial_device</code> and the <code>kind</code> field of the result picks the protocol for you.</p><h2 id="how-to-start" tabindex="-1">How to start <a class="header-anchor" href="#how-to-start" aria-label="Permalink to &quot;How to start&quot;">​</a></h2><ul><li><strong>From chat.</strong> Describe the device in natural language: <ul><li><em>&quot;Add my Arduino on /dev/ttyUSB0 — it prints temperature lines&quot;</em></li><li><em>&quot;Set up the Modbus sensor at slave address 1 on COM3&quot;</em></li><li><em>&quot;This 4-channel thermometer on COM5 needs me to send &#39;A&#39; to make it respond&quot;</em></li></ul></li><li><strong>From the Devices tab.</strong> Open Add Connector, pick <strong>LineText</strong> or <strong>BinaryStream</strong>, click <em>Set up with AI</em>. The chat opens with a pre-filled prompt.</li></ul><h2 id="what-happens-under-the-hood" tabindex="-1">What happens under the hood <a class="header-anchor" href="#what-happens-under-the-hood" aria-label="Permalink to &quot;What happens under the hood&quot;">​</a></h2><h3 id="linetext-devices-that-print-text-lines" tabindex="-1">LineText (devices that print text lines) <a class="header-anchor" href="#linetext-devices-that-print-text-lines" aria-label="Permalink to &quot;LineText (devices that print text lines)&quot;">​</a></h3><ol><li><code>discover_serial_device</code> — the AI tries common baud rates and listens for spontaneous emission. When it sees printable lines, <code>kind: &quot;linetext&quot;</code> is returned with <code>baudRate</code>, <code>terminator</code>, and a <code>sampleText</code> snippet.</li><li><code>read_from_transport</code> — capture another 3-5 seconds of inbound lines to nail down the format. The AI proposes a <code>schema.properties:</code> block where each line shape becomes a typed property using <code>prefix:</code> (for <code>TEMP: 25.5</code>- style lines) or <code>match:</code> regex (for <code>TEMP=25.5</code> or other no-delimiter formats).</li><li><code>write_connector_config</code> — the AI writes the connector file by hand (there&#39;s no <code>compose_linetext_connector</code>; LineText configs are short enough not to need a composer).</li><li><code>reload_connectors</code> + <code>read_property</code> — smoke-test one polled property.</li></ol><h3 id="binarystream-devices-that-emit-binary-frames" tabindex="-1">BinaryStream (devices that emit binary frames) <a class="header-anchor" href="#binarystream-devices-that-emit-binary-frames" aria-label="Permalink to &quot;BinaryStream (devices that emit binary frames)&quot;">​</a></h3><ol><li><p><code>discover_serial_device</code> — sweeps for spontaneous binary emission. When the bytes are non-printable, <code>kind: &quot;binarystream&quot;</code> is returned with <code>baudRate</code> and a <code>sampleHex</code> snippet.</p><p><strong>If the device is silent</strong> (no spontaneous emission), the AI moves on to step 2.</p></li><li><p><code>probe_stimulus</code> — for silent-until-poked devices. The AI tries a default candidate list (common SCPI probes, single ASCII letters, control bytes, Modbus read, …) and reports which stimulus produced a response, plus the exact byte count of the response.</p><p><strong>The reported byte count is the complete burst</strong>, not a truncated chunk. It&#39;s safe to drop into <code>framing.size:</code> directly.</p></li><li><p><code>analyze_binary_frame</code> — the AI asks you to <strong>read 1-3 values off the device&#39;s display</strong> (&quot;the display says 21.4 °C, 50.5 %RH&quot;), passes those</p><ul><li>the captured frame hex to the analyzer, and gets back a paste-ready <code>schemaHint</code> snippet showing the right <code>(offset, width, type, endian, scale)</code> for each field.</li></ul><p>The AI will also ask <strong>&quot;can any of these readings ever go negative?&quot;</strong>. Answer yes (Celsius can dip below zero, signed offsets, bidirectional voltages) or no (humidity, pressure, RPM, lux) — the analyzer drops half the candidate space accordingly and avoids the uint8 vs int8 ambiguity that single-positive-reading data physically can&#39;t resolve.</p></li><li><p><strong>Handle ambiguities.</strong> Sometimes the analyzer returns an <code>ambiguities[]</code> block with a literal <code>disambiguateBy</code> instruction — e.g. <em>&quot;capture another frame where at least one value exceeds 25.5&quot;</em>. This happens when the current values fit in 8 bits and the high bytes are <code>0x00</code>, so uint8 and uint16-LE decode to the same values today but will diverge once readings exceed 25.5 (or whichever boundary).</p><p>The AI reads the instruction to you literally. Heat a probe, recapture, and the AI re-runs <code>analyze_binary_frame</code> with both captures in the <code>samples</code> array. The combined cross-correlation deterministically picks the right type because at least one sample will inevitably have a value the smaller type can&#39;t represent.</p></li><li><p><code>write_connector_config</code> — write the BinaryStream connector. The AI sets <code>framing.size:</code> and <code>framing.request:</code> from the <code>probe_stimulus</code> result, and pastes the <code>schemaHint</code> properties from <code>analyze_binary_frame</code>.</p></li><li><p><code>reload_connectors</code> + <code>read_property</code> — smoke-test.</p></li></ol><h2 id="worked-example-—-silent-4-channel-thermometer" tabindex="-1">Worked example — silent 4-channel thermometer <a class="header-anchor" href="#worked-example-—-silent-4-channel-thermometer" aria-label="Permalink to &quot;Worked example — silent 4-channel thermometer&quot;">​</a></h2><p>A device on COM5 that does nothing until you send <code>A</code>, at which point it returns 16 bytes encoding four channel temperatures.</p><p><strong>Chat:</strong> <em>&quot;Set up the 4-channel thermometer on COM5. I think it needs me to send &#39;A&#39; to make it respond.&quot;</em></p><p><strong>Step 1.</strong> AI calls <code>probe_stimulus({ port: &quot;COM5&quot;, baudRate: 9600 })</code>. The sweep tries the default candidate list and lands on <code>&quot;A&quot;</code> (<code>0x41</code>), reporting <code>receivedBytes: 16</code> and a <code>bestSentHex: &quot;41&quot;</code>.</p><p><strong>Step 2.</strong> AI calls <code>queryHex({ hex: &quot;41&quot; })</code> once more to capture a fresh frame; gets something like <code>0280800101010100D600 E200 E300 0101</code>.</p><p><strong>Step 3.</strong> AI asks: <em>&quot;Can you read the four channel temperatures off the display? Also, can any of these readings ever go below 0 °C?&quot;</em></p><p><strong>You:</strong> <em>&quot;21.4, 22.6, 22.7, 25.7. Yes, the device can read down to -20 °C.&quot;</em></p><p><strong>Step 4.</strong> AI calls <code>analyze_binary_frame({ frameHex: &quot;...&quot;, values: [ {name:&quot;ch1&quot;, value:21.4, canBeNegative:true}, {name:&quot;ch2&quot;, value:22.6, canBeNegative:true}, {name:&quot;ch3&quot;, value:22.7, canBeNegative:true}, {name:&quot;ch4&quot;, value:25.7, canBeNegative:true} ] })</code>. Because one value (25.7) is above 25.5, the uint8 candidate is automatically filtered out — only <code>int16</code> LE with <code>scale: 0.1</code> at offsets 8, 10, 12, 14 fits all four values. The <code>schemaHint</code> comes back paste-ready.</p><p><strong>Step 5.</strong> AI calls <code>write_connector_config</code> with the BinaryStream connector, setting <code>framing.size: 16</code>, <code>framing.request: &quot;41&quot;</code>, and the four channel properties. <code>reload_connectors</code> brings it online. <code>read_property</code> confirms each channel reads its current display value.</p><p>Total elapsed: about 30 seconds of AI time, plus however long it takes you to read the display and answer two questions.</p><h2 id="worked-example-—-arduino-temperature-sketch" tabindex="-1">Worked example — Arduino temperature sketch <a class="header-anchor" href="#worked-example-—-arduino-temperature-sketch" aria-label="Permalink to &quot;Worked example — Arduino temperature sketch&quot;">​</a></h2><p>Sketch on <code>/dev/ttyUSB0</code> prints <code>TEMP: 23.4\\n</code> every second and accepts <code>LED ON\\n</code> / <code>LED OFF\\n</code> to control an LED.</p><p><strong>Chat:</strong> <em>&quot;Add my Arduino on /dev/ttyUSB0 — it prints temperature lines and I can toggle an LED.&quot;</em></p><p><strong>Step 1.</strong> <code>discover_serial_device({ port: &quot;/dev/ttyUSB0&quot; })</code> returns <code>{ kind: &quot;linetext&quot;, baudRate: 115200, terminator: &quot;\\n&quot;, sampleText: &quot;TEMP: 23.4\\n...&quot; }</code>.</p><p><strong>Step 2.</strong> AI captures more lines via <code>read_from_transport</code>, confirms the format is consistent.</p><p><strong>Step 3.</strong> AI writes a LineText connector with <code>temperature: { prefix: &quot;TEMP: &quot;, type: &quot;float&quot;, unit: &quot;C&quot; }</code> and a <code>setLed</code> method.</p><p><strong>Step 4.</strong> <code>reload_connectors</code>. Polled <code>temperature</code> updates as soon as the next line arrives; <code>arduino.setLed(true)</code> sends <code>LED ON\\n</code>.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><h3 id="queryhex-returns-fewer-bytes-than-i-expected" tabindex="-1">&quot;queryHex returns fewer bytes than I expected&quot; <a class="header-anchor" href="#queryhex-returns-fewer-bytes-than-i-expected" aria-label="Permalink to &quot;&quot;queryHex returns fewer bytes than I expected&quot;&quot;">​</a></h3><p>Almost always means <code>framing.size:</code> was set too small (or not at all) and the protocol extracted whatever was in the buffer at the moment the first chunk arrived. Two fixes:</p><ul><li>If you know the response size, set <code>framing.size: N</code>.</li><li>If you don&#39;t, omit framing entirely — the fallback (<code>framing.quietMs</code>, default 50 ms) waits for inter-byte silence and delivers the accumulated burst as one frame.</li></ul><h3 id="polled-properties-stay-null-on-a-silent-device" tabindex="-1">&quot;Polled properties stay null on a silent device&quot; <a class="header-anchor" href="#polled-properties-stay-null-on-a-silent-device" aria-label="Permalink to &quot;&quot;Polled properties stay null on a silent device&quot;&quot;">​</a></h3><p>Add <code>framing.request: &quot;&lt;hex&gt;&quot;</code>. Without it, BinaryStream&#39;s polled reads just return cached values, and the cache never updates because the device never sends anything unsolicited. With it, polled reads auto-trigger a fresh frame when the cache is older than <code>maxStaleMs</code> (default 100 ms). Concurrent reads coalesce — polling four properties triggers ONE send.</p><h3 id="values-readable-but-wrap-at-25-5" tabindex="-1">&quot;Values readable but wrap at 25.5&quot; <a class="header-anchor" href="#values-readable-but-wrap-at-25-5" aria-label="Permalink to &quot;&quot;Values readable but wrap at 25.5&quot;&quot;">​</a></h3><p>You&#39;re decoding as <code>uint8 × 0.1</code> when the device actually uses <code>uint16 little-endian × 0.1</code>. Current values fit in 8 bits and the high bytes are <code>0x00</code>, so today both interpretations read the same value — but uint8 saturates at 25.5 °C. Change <code>width: 1</code> to <code>width: 2</code> and <code>endian: &quot;little&quot;</code> on the affected properties.</p><p>The <code>analyze_binary_frame</code> tool auto-prefers uint16 in this pattern via the high-bytes-zero heuristic and will flag the ambiguity when both fit.</p><h3 id="the-ai-s-schema-is-decoding-the-wrong-channel-for-each-property" tabindex="-1">&quot;The AI&#39;s schema is decoding the wrong channel for each property&quot; <a class="header-anchor" href="#the-ai-s-schema-is-decoding-the-wrong-channel-for-each-property" aria-label="Permalink to &quot;&quot;The AI&#39;s schema is decoding the wrong channel for each property&quot;&quot;">​</a></h3><p>When two adjacent channels have very close readings (say, 22.6 and 22.7), display noise can shuffle them so the analyzer&#39;s lowest-error pick swaps them. The analyzer prefers natural-order assignment when feasible — pass values to the analyzer in the order they appear on the device (ch1, ch2, ch3, ch4) and the heuristic will pick the matching offset order.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/drivers/linetext.html">LineText reference</a></li><li><a href="./../reference/drivers/binary-stream.html">BinaryStream reference</a></li><li><a href="./../reference/drivers/transport.html">Transport reference</a></li><li><a href="./../reference/ai-tools.html">AI Tools reference</a></li><li><a href="./../reference/concepts.html">Concepts</a> — the 5-layer model.</li></ul>',44)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
